package com.smartfix.communitybridge;
import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.security.core.annotation.AuthenticationPrincipal;import com.smartfix.auth.security.SmartFixUserDetails;import com.smartfix.community.dto.AnswerFormCommand;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import jakarta.validation.Valid;import jakarta.servlet.http.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import org.springframework.web.client.*;import java.util.*;
@Controller @ConditionalOnProperty(name="smartfix.community.events.enabled",havingValue="true")
class RemoteThreadController {
 private static final String PATH="/community/questions/900000000001";private final RemoteThreadClient client;RemoteThreadController(RemoteThreadClient client){this.client=client;}
 @SuppressWarnings("unchecked") private Map<UUID,Long> keys(HttpSession session){synchronized(session){var keys=(Map<UUID,Long>)session.getAttribute("communityRemoteKeys");if(keys==null){keys=new LinkedHashMap<>();session.setAttribute("communityRemoteKeys",keys);}return keys;}}
 @GetMapping("/community/migration-demo") String entry(){return "redirect:"+PATH;}
 @GetMapping(PATH) String get(@AuthenticationPrincipal SmartFixUserDetails actor,Model model,HttpSession session,HttpServletResponse response){var keys=keys(session);UUID key=UUID.randomUUID();synchronized(keys){if(keys.size()>=100)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Too many open forms");keys.put(key,actor.getUserId());}model.addAttribute("commandKey",key);model.addAttribute("answerCommand",new AnswerFormCommand());return render(actor,model,response);}
 @PostMapping(PATH+"/answers") String post(@AuthenticationPrincipal SmartFixUserDetails actor,@RequestParam UUID commandKey,@Valid @ModelAttribute("answerCommand")AnswerFormCommand answer,BindingResult errors,Model model,HttpSession session,HttpServletResponse response){var keys=keys(session);synchronized(keys){if(!actor.getUserId().equals(keys.get(commandKey)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Form expired");}model.addAttribute("commandKey",commandKey);
  if(!errors.hasErrors())try{client.answer(actor,commandKey,answer.getBody());return "redirect:"+PATH;}catch(RestClientResponseException e){response.setStatus(e.getStatusCode().is4xxClientError()?e.getStatusCode().value():503);model.addAttribute("submissionMessage",e.getStatusCode().is4xxClientError()?"The answer was refused. Check the text or use the same form to retry.":"The result is not confirmed. Keep this form and retry with the same key.");}catch(RestClientException e){response.setStatus(503);model.addAttribute("submissionMessage","The result is not confirmed. Keep this form and retry with the same key.");}
  return render(actor,model,response);
 }
 private String render(SmartFixUserDetails actor,Model model,HttpServletResponse response){try{model.addAttribute("thread",client.detail(actor));}catch(RestClientException e){response.setStatus(503);model.addAttribute("loadMessage","Discussion temporarily unavailable. Your submission is not confirmed; keep the same form to retry.");}return "community/remote-thread";}
 @ExceptionHandler(ResponseStatusException.class) org.springframework.http.ResponseEntity<Map<String,String>> statusError(ResponseStatusException e){return org.springframework.http.ResponseEntity.status(e.getStatusCode()).body(Map.of("code","REQUEST_REFUSED"));}
}
